def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    my_last, opp_last = history[-1]

    opp_def_10 = 0
    my_def_10 = 0
    opp_def_5 = 0
    for i in range(n - 1, -1, -1):
        if n - i <= 10:
            if history[i][1] == 'D':
                opp_def_10 += 1
            if history[i][0] == 'D':
                my_def_10 += 1
        if n - i <= 5:
            if history[i][1] == 'D':
                opp_def_5 += 1
        if n - i > 10:
            break

    opp_total_def = 0
    cc = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_total_def += 1
        if history[i][0] == 'C' and history[i][1] == 'C':
            cc += 1

    opp_coop_rate = 1.0 - float(opp_total_def) / float(n)

    # Sustained defector: stop feeding them.
    if opp_def_5 >= 5 or opp_def_10 >= 7:
        return 'D'

    # Opponent currently defecting.
    if opp_last == 'D':
        if opp_def_10 >= 3:
            return 'D'
        # Fresh isolated defection: retaliate but keep door open.
        if opp_coop_rate > 0.5:
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        return 'D'

    # Opponent cooperated.
    if opp_coop_rate < 0.35:
        # They mostly defect but just cooperated; occasional probe.
        if rng.random() < 0.6:
            return 'D'
        return 'C'
    if opp_total_def == 0:
        # All cooperation so far: cooperate, but probe in late game.
        if n >= 90:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'
    if opp_def_5 >= 2:
        if rng.random() < 0.5:
            return 'D'
        return 'C'
    # Tit-for-tat-like: mirror cooperation, with forgiveness after our own defections.
    if my_last == 'D' and my_def_10 > opp_def_10 + 1:
        return 'C'
    return 'C'
